mapper.select:
select o.*,u.name as user_name from orders o left join address_book ab on ab.id = o.address_book_id left join `user` u on u.id = o.user_id
o.status = #{status} and ab.phone like concat('%',#{phone},'%') and o.number like concat('%',#{number},'%') and o.order_time >= #{beginTime} and o.order_time <= #{endTime}
order by o.order_time desc

select od.id, od.name, od.order_id, od.dish_id, od.setmeal_id, od.flavor_id, (SELECT GROUP_CONCAT(f.flavor_name) FROM flavor f WHERE FIND_IN_SET(f.id, od.flavor_id)) AS flavor_name, od.flavor_val, od.dish_copies, od.setmeal_copies, od.amount, od.image from order_detail od where od.order_id in
#{orderId}
order by od.id
